import hashlib,json,re
from pathlib import Path
rows=[]; cases={}; modules={}
def digest(data):return hashlib.sha256(data).hexdigest()
def evidence(file,needle,scope):
 path=Path('tests/'+file+'.test.ts');text=path.read_text();matches=list(re.finditer(r'(?<![.\w])test\(\s*([\s\S]*?),\s*(?:async\s*)?\([^)]*\)\s*=>',text));found=[(i,m)for i,m in enumerate(matches)if needle in m[1]]
 assert len(found)==1,(file,needle,len(found));i,m=found[0];end=matches[i+1].start()if i+1<len(matches)else len(text);excerpt=text[m.start():end];key=file+':'+needle
 if key not in cases:cases[key]=dict(file=str(path),line=text[:m.start()].count('\n')+1,sourceTitleExpression=m[1].strip(),testNamePattern=re.escape(needle),selectorKind='constant substring matching runtime test titles; parameterized templates select all relevant family cases',fileSha256=digest(path.read_bytes()),caseExcerptSha256=digest(excerpt.encode()),caseExcerptBoundary='test declaration through the next test declaration (or EOF), not a parsed AST function',assertionLines=[text[:m.start()+a.start()].count('\n')+1 for a in re.finditer(r'\bassert\.',excerpt)],reviewedAssertionScope=scope,execution='Source assertions independently reviewed. Generator does not execute tests; use parent final acceptance and focused logs.')
 return key

def source(path):
 if path not in modules:
  p=Path('src/'+path+'.ts');s=p.read_text();matches=list(re.finditer(r'^(?:export )?(?:async )?(?:function|class)\s+(\w+)|^\s{2}(?:private )?(\w+)\([^\n]*\)\s*:',s,re.M));modules[path]=dict(file=str(p),fileSha256=digest(p.read_bytes()),entryPoints=[dict(name=m[1]or m[2],line=s[:m.start()].count('\n')+1)for m in matches],scope='Locations index source implementation; they do not certify every branch.')
 return path

def add(exam,id,workflow,tests,implementation,limits,scope='bounded-direct-and-composed'):
 refs=[evidence(*t)for t in tests];rows.append(dict(exam=exam,id=id,workflow=workflow,assertionEvidenceIds=refs,implementationIds=[source(p)for p in implementation],assessment=scope,remainingBoundary=limits,completeIOSOrObjectiveClaim=False))
